INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (29, 1, 4, 'Computer Science', 'computer_science', 'The Department of Computer Science (DCSC) offers UG-PG integrated, M.Sc. CS, M.Sc. AI, and Ph.D. programmes designed for global excellence.', 'The Department of Computer Science at CUSB is committed to research-led teaching in foundational and applied computing. With a curriculum aligned to NEP 2020 and industry requirements, students gain expertise in algorithms, artificial intelligence, data science, and software engineering — preparing them for careers in technology and research across India and globally.', 'CUET (UG/PG) conducted by NTA', 'Established: 2009', 'published', 1, 29);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (30, 1, 4, 'Mathematics', 'mathematics', 'The Department of Mathematics builds strong foundations in pure and applied mathematics for teaching, research, analytics, and scientific computing.', 'The department focuses on mathematical reasoning, modelling, analysis, and problem solving. Students engage with classical theory and modern applications across computation, finance, data analysis, and interdisciplinary research.', 'CUET (UG/PG) conducted by NTA', 'Established: 2009', 'published', 1, 30);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (31, 1, 4, 'Statistics', 'statistics', 'The Department of Statistics prepares students in statistical theory, applied data analysis, survey methods, and computational statistics.', 'The department connects rigorous statistical foundations with real-world data problems in science, social research, policy, industry, and technology.', 'CUET PG', 'Established: 2009', 'published', 1, 31);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (32, 1, 1, 'Bioinformatics', 'bioinformatics', 'The Department of Bioinformatics blends biology, computer science, and statistics to study biological data at scale.', 'The department supports interdisciplinary learning in genomics, computational biology, biological databases, and data-driven life science research.', 'CUET PG', 'Established: 2009', 'published', 1, 32);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (33, 1, 1, 'Geology', 'geology', 'The Department of Geology studies earth materials, processes, resources, hazards, and environmental change.', 'The department develops field-based and laboratory skills for understanding the Earth system, natural resources, geohazards, and sustainable development.', 'CUET PG', 'Established: 2009', 'published', 1, 33);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (34, 1, 1, 'Geography', 'geography', 'The Department of Geography explores physical landscapes, human environments, spatial planning, and geospatial technologies.', 'The department combines fieldwork, spatial analysis, GIS, remote sensing, and social-environmental inquiry to understand changing regions and communities.', 'CUET PG', 'Established: 2009', 'published', 1, 34);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (35, 1, 1, 'Life Science', 'life_science', 'The Department of Life Science provides broad training in biological systems from molecules to ecosystems.', 'The department encourages laboratory learning and research across cell biology, microbiology, plant sciences, animal sciences, and ecology.', 'CUET PG', 'Established: 2009', 'published', 1, 35);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (36, 1, 1, 'Biotechnology', 'biotechnology', 'The Department of Biotechnology applies biological knowledge to health, agriculture, environment, and industrial innovation.', 'The department integrates molecular biology, genetics, bioprocessing, and modern laboratory practice for research and technology-oriented careers.', 'CUET PG', 'Established: 2009', 'published', 1, 36);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (37, 1, 1, 'Environmental Sciences', 'environmental_sciences', 'The Department of Environmental Sciences studies environmental systems, pollution, conservation, and sustainable resource management.', 'The department prepares students to address environmental challenges through field studies, laboratory analysis, policy awareness, and interdisciplinary research.', 'CUET PG', 'Established: 2009', 'published', 1, 37);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (38, 1, 2, 'Psychological Sciences', 'psychological_sciences', 'The Department of Psychological Sciences studies behaviour, cognition, development, mental health, and human well-being.', 'The department combines theory, assessment, research methods, and applied practice to prepare students for counselling, research, and human service roles.', 'CUET PG', 'Established: 2009', 'published', 1, 38);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (39, 1, 6, 'Historical Studies', 'historical_studies', 'The Department of Historical Studies examines societies, cultures, institutions, and ideas across time.', 'The department promotes critical historical inquiry through archival work, interpretation of sources, regional history, and wider global perspectives.', 'CUET PG', 'Established: 2009', 'published', 1, 39);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (40, 1, 3, 'Law & Governance', 'law_governance', 'The Department of Law & Governance studies legal systems, constitutional values, public institutions, and justice.', 'The department combines legal education, governance studies, research, advocacy skills, and public service orientation.', 'CUET (UG/PG)', 'Established: 2009', 'published', 1, 40);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (41, 1, 5, 'Chemistry', 'chemistry', 'The Department of Chemistry studies matter, reactions, materials, analysis, and chemical processes.', 'The department develops experimental and theoretical understanding across organic, inorganic, physical, analytical, and materials chemistry.', 'CUET PG', 'Established: 2009', 'published', 1, 41);
INSERT INTO departments (id, language_id, school_id, name, slug, description, vision, mission, office_location, status, is_active, sort_order) VALUES (42, 1, 5, 'Physics', 'physics', 'The Department of Physics investigates matter, energy, materials, space, and fundamental laws of nature.', 'The department combines theory, experiments, computation, and instrumentation to prepare students for research and technology careers.', 'CUET PG', 'Established: 2009', 'published', 1, 42);
