INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (67, 1, 29, 'B.Sc. + M.Sc. Computer Science', 'computer-science-b-sc-m-sc-computer-science', 'undergraduate', '5 Years', 25, '10+2 with Math', 'A five-year comprehensive integrated honours programme covering fundamental coding, architectures, web programming and machine learning, aligning with NEP 2020 exit options.', '{}', 'published', 1, 67);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (68, 1, 29, 'M.Sc. Computer Science', 'computer-science-m-sc-computer-science', 'postgraduate', '2 Years', 40, 'BCA / B.Sc. CS / B.Tech', 'An advanced curriculum emphasizing database management, network security, software engineering, and cloud platforms, concluding with a research dissertation project.', '{}', 'published', 1, 68);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (69, 1, 29, 'M.Sc. Artificial Intelligence', 'computer-science-m-sc-artificial-intelligence', 'postgraduate', '2 Years', 20, 'BCA / B.Sc. CS / B.Tech', 'Focuses on PyTorch/TensorFlow frameworks, deep learning models, natural language processing, computer vision networks, and ethical artificial intelligence constructs.', '{}', 'published', 1, 69);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (70, 1, 29, 'Ph.D. Computer Science', 'computer-science-ph-d-computer-science', 'doctoral', '3–5 Years', NULL, 'M.Sc. CS / M.Tech (55%+)', 'Scholarly research domains covering pattern recognition, cryptography, network routing protocols, medical image analysis, and algorithm complexity evaluations.', '{}', 'published', 1, 70);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (71, 1, 30, 'Integrated B.Sc. + M.Sc. Mathematics', 'mathematics-integrated-b-sc-m-sc-mathematics', 'undergraduate', '5 Years', 30, '10+2 with Math', 'Combined basic and advanced curriculum in mathematical analysis and algebra.', '{}', 'published', 1, 71);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (72, 1, 30, 'M.Sc. Mathematics', 'mathematics-m-sc-mathematics', 'postgraduate', '2 Years', 40, 'B.Sc. with Math', 'Core postgraduate course with advanced real analysis, algebra, and topology.', '{}', 'published', 1, 72);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (73, 1, 30, 'Ph.D. Mathematics', 'mathematics-ph-d-mathematics', 'doctoral', '3–5 Years', NULL, 'M.Sc. Mathematics', 'Research studies in core areas of algebra, analysis, and computation.', '{}', 'published', 1, 73);
INSERT INTO programs (id, language_id, department_id, name, slug, level, duration_text, intake_capacity, eligibility, description, fee_summary, status, is_active, sort_order) VALUES (74, 1, 31, 'Integrated B.Sc. + M.Sc. Statistics', 'statistics-integrated-b-sc-m-sc-statistics', 'undergraduate', '5 Years', 25, '10+2 with Math', 'Combined course in statistical foundations and computations.', '{}', 'published', 1, 74);
