INSERT INTO hostels (id, language_id, name, slug, description, capacity, location, status, is_active) VALUES (5, 1, 'Gargi Sadan & Maitreyi Sadan', 'girls_hostels', 'The girls hostels provide comfortable and safe lodging for postgraduate and research students. Managed by a dedicated female warden team, it boasts robust security measures, a modern common room with a TV, daily newspaper service, and clean dining services. Facilities: Common Room, TV, Reading Room, Gym, Wi-Fi. Mess: Co-operative, Vegetarian & Non-Veg menu options. Security: 24/7 Female Guards, CCTV Surveillance', 150, 'girls', 'published', 1);
INSERT INTO hostels (id, language_id, name, slug, description, capacity, location, status, is_active) VALUES (6, 1, 'Aryabhatta Sadan & Malviya Sadan', 'boys_hostels', 'The boys hostels offer secure, spacious, and student-friendly accommodation. The rooms are double-sharing, well-ventilated, and furnished with a bed, table, and wardrobe. Facilities include an outdoor playground, high-speed Wi-Fi, indoor games, and clean drinking water units. Facilities: Table Tennis, Badminton Court, Wi-Fi, TV Lounge. Mess: Student-run mess committee, Weekly menu reviews. Security: 24/7 Security Guards, Gate Register Log', 200, 'boys', 'published', 1);
